using InterviewAPI.DTOs.Biometrics;
using InterviewAPI.DTOs.Session;
using InterviewAPI.Services.Interfaces;
using Microsoft.AspNetCore.Mvc;
using Moq;
using Xunit;

namespace InterviewAPI.Tests;

public class FinalWorkbookUtcidTests
{
 [Theory][MemberData(nameof(Cases195))] public async Task Integrity_policy_status(string id,int n){var(c,s,_,u)=ReadTest.Create();var sid=n==5?Guid.Empty:Guid.NewGuid();if(n==4)s.Setup(x=>x.GetIntegrityPolicyStatusAsync(u,sid,It.IsAny<CancellationToken>())).ThrowsAsync(new KeyNotFoundException("missing"));else s.Setup(x=>x.GetIntegrityPolicyStatusAsync(u,sid,It.IsAny<CancellationToken>())).ReturnsAsync(new IntegrityPolicyStatusResponse{Accepted=n is 2 or 6,AcceptedAt=n==6?DateTime.UtcNow:null});var r=await c.GetIntegrityPolicyStatus(sid,default);Assert.Equal(n==4?404:200,ReadTest.Status(r));Assert.StartsWith("FUNC195",id);}
 [Theory][MemberData(nameof(Cases196))] public async Task Accept_integrity_policy(string id,int n){var(c,s,_,u)=ReadTest.Create();var sid=n==5?Guid.Empty:Guid.NewGuid();if(n==3)s.Setup(x=>x.AcceptIntegrityPolicyAsync(u,sid,It.IsAny<CancellationToken>())).ThrowsAsync(new KeyNotFoundException());else if(n==4)s.Setup(x=>x.AcceptIntegrityPolicyAsync(u,sid,It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException());else s.Setup(x=>x.AcceptIntegrityPolicyAsync(u,sid,It.IsAny<CancellationToken>())).ReturnsAsync(new IntegrityPolicyStatusResponse{Accepted=true,AcceptedAt=DateTime.UtcNow});Assert.Equal(n==3?404:n==4?400:200,ReadTest.Status(await c.AcceptIntegrityPolicy(sid,default)));Assert.StartsWith("FUNC196",id);}
 [Theory][MemberData(nameof(Cases197))] public async Task Active_session(string id,int n){var(c,s,_,u)=ReadTest.Create();ActiveSessionResponse? value=n==2?null:new(){SessionId=n==5?Guid.Empty:Guid.NewGuid(),Status=n==3?"Paused":"InProgress",RemainingSeconds=n==6?int.MaxValue:60};s.Setup(x=>x.GetActiveSessionAsync(u,It.IsAny<CancellationToken>())).ReturnsAsync(value);Assert.Equal(200,ReadTest.Status(await c.GetActiveSession(default)));s.Verify(x=>x.GetActiveSessionAsync(u,It.IsAny<CancellationToken>()));Assert.StartsWith("FUNC197",id);}
 [Theory][MemberData(nameof(Cases198))] public async Task Issue_challenge(string id,int n){var(c,b,_,u)=VerifyTest.Create();var sid=n==5?Guid.Empty:Guid.NewGuid();var modality=n==3?"bad":n%2==0?"voice":"face";if(n==4)b.Setup(x=>x.IssueChallengeAsync(u,sid,It.IsAny<string>(),It.IsAny<CancellationToken>())).ThrowsAsync(new KeyNotFoundException());else if(n==6)b.Setup(x=>x.IssueChallengeAsync(u,sid,It.IsAny<string>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception());else b.Setup(x=>x.IssueChallengeAsync(u,sid,It.IsAny<string>(),It.IsAny<CancellationToken>())).ReturnsAsync(new VerificationChallengeResponse{Modality=modality,ExpiresInSeconds=20});Assert.Equal(n==3?400:n==4?404:n==6?503:200,VerifyTest.Status(await c.GetChallenge(sid,modality,default)));Assert.StartsWith("FUNC198",id);}
 [Theory][MemberData(nameof(Cases199))] public async Task Voice_identity(string id,int n){var t=new VoiceAnswerIdentityUtcidTests();await (n switch{1=>t.Matching_voice_returns_transcript(),2=>t.Mismatch_strike_is_valid_result(),3=>t.Missing_identity_prevents_check(),4=>t.Missing_check_is_not_found(),5=>t.Check_id_boundaries_are_forwarded(),_=>t.Dependency_failure_returns_service_unavailable()});Assert.StartsWith("FUNC199",id);}
 [Theory][MemberData(nameof(Cases207))] public async Task Pause_resume(string id,int n){var t=new PauseResumeUtcidTests();await(n switch{1=>t.Pause_returns_quota_state(),2=>t.Unpause_returns_recalculated_timer(),3=>t.Missing_identity_prevents_pause_and_unpause(),4=>t.Pause_rule_failure_is_safely_mapped(),5=>t.Session_id_boundaries_are_forwarded(),_=>t.Unpause_dependency_failure_returns_service_unavailable()});Assert.StartsWith("FUNC207",id);}
 [Theory][MemberData(nameof(Cases208))] public async Task Monitor_face(string id,int n){var t=new InSessionFaceUtcidTests();await(n switch{1=>t.Passed_check_is_returned(),2=>t.Failed_identity_check_is_valid_result(),3=>t.Missing_identity_prevents_check(),4=>t.Missing_check_is_not_found(),5=>t.Check_id_boundaries_are_forwarded(),_=>t.Dependency_failure_returns_service_unavailable()});Assert.StartsWith("FUNC208",id);}

 public static IEnumerable<object[]> Cases195()=>Cases("FUNC195-USR"); public static IEnumerable<object[]> Cases196()=>Cases("FUNC196-USR"); public static IEnumerable<object[]> Cases197()=>Cases("FUNC197-USR"); public static IEnumerable<object[]> Cases198()=>Cases("FUNC198-USR"); public static IEnumerable<object[]> Cases199()=>Cases("FUNC199-USR"); public static IEnumerable<object[]> Cases207()=>Cases("FUNC207-USR"); public static IEnumerable<object[]> Cases208()=>Cases("FUNC208-USR");
 static IEnumerable<object[]> Cases(string f)=>Enumerable.Range(1,6).Select(i=>new object[]{$"{f}-UTCID{i:00}",i});
}

public class FinalEligibilityOwnershipUtcidTests
{
 [Theory][MemberData(nameof(Cases200))] public async Task Report_eligibility(string id,int n){var(c,s,_,u)=ReadTest.Create(n!=3);if(n==3){Assert.IsType<UnauthorizedObjectResult>(await c.GetFeedbackEligibility(default));s.VerifyNoOtherCalls();return;}s.Setup(x=>x.GetFeedbackEligibilityAsync(u,It.IsAny<CancellationToken>())).ReturnsAsync(new FeedbackEligibilityResponse{Eligible=n is 1 or 6,QualifyingSessionCount=n==5?int.MaxValue:n});Assert.Equal(200,ReadTest.Status(await c.GetFeedbackEligibility(default)));Assert.StartsWith("FUNC200",id);}
 [Theory][MemberData(nameof(Cases201))] public async Task Session_report_eligibility(string id,int n){var(c,s,_,u)=ReadTest.Create(n!=3);var sid=n==5?Guid.Empty:Guid.NewGuid();if(n==3){Assert.IsType<UnauthorizedObjectResult>(await c.GetSessionFeedbackEligibility(sid,default));return;}if(n==4)s.Setup(x=>x.GetSessionFeedbackEligibilityAsync(u,sid,It.IsAny<CancellationToken>())).ThrowsAsync(new KeyNotFoundException());else s.Setup(x=>x.GetSessionFeedbackEligibilityAsync(u,sid,It.IsAny<CancellationToken>())).ReturnsAsync(new SessionFeedbackEligibilityResponse{SessionId=sid,Status=n==2?"Cancelled":"Completed",CanGeneratePerformanceReport=n is 1 or 6});Assert.Equal(n==4?404:200,ReadTest.Status(await c.GetSessionFeedbackEligibility(sid,default)));Assert.StartsWith("FUNC201",id);}
 [Theory][MemberData(nameof(Cases202))] public async Task Verify_ownership(string id,int n){var(c,s,_,u)=ReadTest.Create();var sid=n==5?Guid.Empty:Guid.NewGuid();s.Setup(x=>x.OwnsSessionAsync(u,sid,It.IsAny<CancellationToken>())).ReturnsAsync(n is 1 or 5 or 6);Assert.Equal(n is 1 or 5 or 6?200:404,ReadTest.Status(await c.Owns(sid,default)));s.VerifyAll();Assert.StartsWith("FUNC202",id);}
 [Theory][MemberData(nameof(Cases203))] public async Task Get_user_sessions(string id,int n){var t=new ListUserSessionsUtcidTests();await(n switch{1=>t.Returns_owned_session_items(),2=>t.Empty_session_list_is_valid(),3=>t.Missing_identity_returns_service_unavailable_without_query(),4=>t.Repository_failure_returns_service_unavailable(),5=>t.Large_result_boundary_is_not_truncated(),_=>t.Cancellation_failure_is_safely_mapped()});Assert.StartsWith("FUNC203",id);}
 public static IEnumerable<object[]> Cases200()=>Cases("FUNC200-USR");public static IEnumerable<object[]> Cases201()=>Cases("FUNC201-USR");public static IEnumerable<object[]> Cases202()=>Cases("FUNC202-USR");public static IEnumerable<object[]> Cases203()=>Cases("FUNC203-USR");
 static IEnumerable<object[]> Cases(string f)=>Enumerable.Range(1,6).Select(i=>new object[]{$"{f}-UTCID{i:00}",i});
}
